import{_ as e,o as t,c as n,a5 as o}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"3. 编写并运行您的第一个程序","description":"The Little Book of C 中文版 — 3. 编写并运行您的第一个程序","frontmatter":{"title":"3. 编写并运行您的第一个程序","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","01-入门","中文"],"description":"The Little Book of C 中文版 — 3. 编写并运行您的第一个程序","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":3,"sidebarWeight":3,"alternateZh":"/posts/c教程/zh-CN/01-入门/003-Writing and Running Your First Program","alternateEn":"/posts/c教程/en-US/01-Getting Started/003-Writing and Running Your First Program"},"headers":[],"relativePath":"posts/c教程/zh-CN/01-入门/003-Writing and Running Your First Program.md","filePath":"posts/c教程/zh-CN/01-入门/003-Writing and Running Your First Program.md","lastUpdated":1790163617000}'),s={name:"posts/c教程/zh-CN/01-入门/003-Writing and Running Your First Program.md"};function i(l,a,p,r,d,c){return t(),n("div",null,[...a[0]||(a[0]=[o(`<p>[English version](/posts/c教程/en-US/01-Getting Started/003-Writing and Running Your First Program)</p><p>现在您的编译器已准备就绪，是时候编写您的第一个真正的 C 程序了。这就是奇迹发生的地方，您将编写纯文本，将其编译成机器指令，然后观察您的计算机准确地遵循您的命令。</p><p>C 不会隐藏幕后发生的事情。每一步，编写、编译、链接、运行，都是可见的并在您的控制之下。</p><h4 id="小代码" tabindex="-1">小代码 <a class="header-anchor" href="#小代码" aria-label="Permalink to &quot;小代码&quot;">​</a></h4><p>创建一个新文件，名为<code>hello.c</code>并输入以下代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Hello, world!\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>然后，编译并运行它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc hello.c -o hello</span></span>
<span class="line"><span>./hello</span></span></code></pre></div><p>你应该看到：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello, world!</span></span></code></pre></div><h4 id="分解它" tabindex="-1">分解它 <a class="header-anchor" href="#分解它" aria-label="Permalink to &quot;分解它&quot;">​</a></h4><p><code>#include &lt;stdio.h&gt;</code>这告诉编译器使用标准输入/输出库，它提供了<code>printf</code>功能。</p><p><code>int main(void)</code>每个 C 程序都以<code>main</code>功能。这是执行开始的入口点。</p><p><code>printf(&quot;Hello, world!\\n&quot;);</code>这会将文本打印到屏幕上。这<code>\\n</code>意思是“换行”，所以下一个输出从新行开始。</p><p><code>return 0;</code>什么时候<code>main</code>返回 0，它告诉操作系统您的程序已成功完成。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>你的“Hello, world”可能看起来很简单，但它代表了一个完整的过程：</p><ol><li>编译器翻译你的文本（<code>hello.c</code>) 转换为目标代码 (<code>hello.o</code>).</li><li>链接器将该代码与标准库结合起来。</li><li>可执行文件（<code>hello</code>）是纯机器指令。 4.操作系统加载并运行它。</li></ol><p>理解这个流程是 C 语言的特别之处，它不仅仅是编写代码，而是了解代码如何成为软件。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><p>将消息更改为<code>&quot;Hello, C learner!&quot;</code>并重新编译。</p><p>添加另一行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;This is my first C program.\\n&quot;);</span></span></code></pre></div><p>尝试省略分号，编译器会显示什么错误？</p><p>尝试删除<code>#include &lt;stdio.h&gt;</code>，然后会发生什么？</p><p>尝试并打破事物。每个错误都会告诉你 C 是如何思考的。</p><p>您刚刚编写并运行了第一个 C 程序，这是您和机器之间的直接对话。从这里开始，每一段新代码都建立在这个简单的控制和理解时刻之上。</p>`,27)])])}const g=e(s,[["render",i]]);export{u as __pageData,g as default};
